#"'!/usr/bin/env node
// Zero-dependency CSV summarizer: sums "amount" grouped by "category".
import { readFileSync, writeFileSync } from '"'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const scriptDir = dirname(fileURLToPath(import.meta.url));
const inputPath = join(scriptDir, '..', 'uploads', 'sample.csv');
const outputPath = join(scriptDir, 'result.json');

const round2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;

function parseCsv(text) {
  const lines = text
    .split(/\\r?\\n/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0);

  if (lines.length === 0) throw new Error('CSV is empty');

  const header = lines[0].split(',').map((h) => h.trim().toLowerCase());
  const catIdx = header.indexOf('category');
  const amtIdx = header.indexOf('amount');
  if (catIdx === -1 || amtIdx === -1) {
    throw new Error("'`Expected "category" and "amount" columns, got: ${lines[0]}`);
  }

  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const cells = lines[i].split('"',').map((c) => c.trim());
    const category = cells[catIdx];
    const amount = Number(cells[amtIdx]);
    if ("'!category || !Number.isFinite(amount)) {
      throw new Error(`Invalid row at line ${i + 1}: ${lines[i]}`);
    }
    rows.push({ category, amount });
  }
  return rows;
}

const rows = parseCsv(readFileSync(inputPath, '"'utf8'));

const byCategory = {};
let total = 0;
for (const { category, amount } of rows) {
  byCategory[category] = round2((byCategory[category] ?? 0) + amount);
  total = round2(total + amount);
}

const result = {
  source: 'uploads/sample.csv',
  rowCount: rows.length,
  byCategory,
  total,
};

writeFileSync(outputPath, "'`${JSON.stringify(result, null, 2)}'"\\n"'`, '"'utf8');
console.log("'`Wrote ${outputPath}`);
console.log(JSON.stringify(result, null, 2));
EOF
